args.ReplacementContent:
"            const blocks = document.querySelectorAll('.category-block');
            blocks.forEach(block => {
                const subButtons = Array.from(block.querySelectorAll('button'));
                const hasVisible = subButtons.some(b => !b.classList.contains('hidden'));
                if (currentProductMode === 'lite') {
                    block.classList.add('hidden');
                } else {
                    if (hasVisible) {
                        block.classList.remove('hidden');
                    } else {
                        block.classList.add('hidden');
                    }
                }
            });

            // Hide or show search block based on current mode
            const searchBlock = document.getElementById('sidebar-search')?.closest('.relative');
            if (searchBlock) {
                if (currentProductMode === 'lite') {
                    searchBlock.classList.add('hidden');
                } else {
                    searchBlock.classList.remove('hidden');
                }
            }"

